CREATE TABLE IF NOT EXISTS league_snapshots (id BIGSERIAL PRIMARY KEY, provider VARCHAR(32) NOT NULL, league_id VARCHAR(32) NOT NULL, season VARCHAR(8), observed_at TIMESTAMPTZ NOT NULL, schema_version INTEGER NOT NULL DEFAULT 1, payload JSONB NOT NULL, CONSTRAINT uq_league_snapshot UNIQUE(provider,league_id,observed_at));
CREATE INDEX IF NOT EXISTS ix_league_snapshots_league_id ON league_snapshots(league_id);
CREATE TABLE IF NOT EXISTS players (id BIGSERIAL PRIMARY KEY, provider VARCHAR(32) NOT NULL, provider_player_id VARCHAR(64) NOT NULL, name VARCHAR(160) NOT NULL, position VARCHAR(12) NOT NULL, team VARCHAR(12), observed_at TIMESTAMPTZ NOT NULL, schema_version INTEGER NOT NULL DEFAULT 1, CONSTRAINT uq_player_snapshot UNIQUE(provider,provider_player_id,observed_at));
CREATE TABLE IF NOT EXISTS drafts (id BIGSERIAL PRIMARY KEY, provider_draft_id VARCHAR(64) UNIQUE NOT NULL, league_id VARCHAR(32) NOT NULL, season VARCHAR(8) NOT NULL, draft_type VARCHAR(32) NOT NULL, status VARCHAR(24) NOT NULL, observed_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS draft_picks (id BIGSERIAL PRIMARY KEY, provider_draft_id VARCHAR(64) NOT NULL, pick_no INTEGER NOT NULL, round INTEGER, manager_id VARCHAR(64) NOT NULL, player_id VARCHAR(64), observed_at TIMESTAMPTZ NOT NULL, CONSTRAINT uq_draft_pick UNIQUE(provider_draft_id,pick_no));
CREATE TABLE IF NOT EXISTS projection_snapshots (id BIGSERIAL PRIMARY KEY, player_id VARCHAR(64) NOT NULL, source VARCHAR(64) NOT NULL, horizon VARCHAR(16) NOT NULL, scoring_key VARCHAR(80) NOT NULL, median DOUBLE PRECISION NOT NULL, floor DOUBLE PRECISION, ceiling DOUBLE PRECISION, observed_at TIMESTAMPTZ NOT NULL, effective_at TIMESTAMPTZ, schema_version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS ix_projection_lookup ON projection_snapshots(player_id,horizon,scoring_key,observed_at);
CREATE TABLE IF NOT EXISTS market_value_snapshots (id BIGSERIAL PRIMARY KEY, asset_id VARCHAR(64) NOT NULL, source VARCHAR(64) NOT NULL, format_key VARCHAR(80) NOT NULL, value DOUBLE PRECISION NOT NULL, observed_at TIMESTAMPTZ NOT NULL, schema_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS recommendations (id BIGSERIAL PRIMARY KEY, league_id VARCHAR(32), kind VARCHAR(32) NOT NULL, model_version VARCHAR(32) NOT NULL, data_version VARCHAR(64) NOT NULL, seed INTEGER, input_hash VARCHAR(64) NOT NULL, output JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL, quality_state VARCHAR(24) NOT NULL);
CREATE TABLE IF NOT EXISTS feature_flags (key VARCHAR(80) PRIMARY KEY, enabled BOOLEAN NOT NULL DEFAULT FALSE, updated_at TIMESTAMPTZ NOT NULL);
